import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`research-analyst`,heroTitle:`Market research and analysis, done for you`,heroSubtitle:`Perplexity Computer gathers the data, runs the analysis, and delivers a sourced report — automatically.`,inputUrlCta:`Run my research`,inputUrlPlaceholder:`your research question`,inputUrlPrefill:`Research this question: {url}. Act as a research analyst. 1) Break the question into subtopics, hypotheses, data needs, and decision criteria. 2) Gather credible market sources, company data, customer signals, competitor evidence, and trend context. 3) Analyze the findings for market size, segments, drivers, risks, opportunities, and strategic implications. 4) Build a sourced report with an executive summary, key charts or tables, evidence notes, and recommended next steps. 5) Organize source links, assumptions, and open questions in Google Sheets, Notion, Gmail, or Slack.`,heroOverlaySteps:[`Breaking the research question into hypotheses, sources, and decision criteria`,`Gathering market, competitor, customer, and trend evidence`,`Analyzing segments, drivers, risks, and opportunities`,`Sourced research report ready to review`],generatingSteps:[`Reading {url} to understand the research question and decision context`,`Designing agents to gather market, competitor, customer, and trend evidence`,`Configuring analysis for segments, drivers, risks, opportunities, and implications`,`Preparing a sourced report with summary, evidence notes, and recommendations`],featureSectionTitle:`From question to sourced report`,featureCardTitles:[`Connects to your research stack`,`Outputs ready for decisions`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Gmail, Slack — Computer keeps sources, analysis, tables, and stakeholder updates organized across your research workflow.`,`Market maps. Competitor summaries. Data tables. Sourced reports. Executive briefs. Computer turns open-ended questions into evidence your team can use.`],capabilitySectionTitle:`Your research analyst, on autopilot`,capabilitySectionSubtitle:`Ask the question, step away, and come back to a sourced report with analysis and recommendations.`,capabilityCards:[{title:`Market Research`,description:`Computer can gather credible sources, company evidence, customer signals, and competitor context for your research question.`},{title:`Data Analysis`,description:`Computer can synthesize market size, segments, drivers, risks, opportunities, and patterns into a decision-ready view.`},{title:`Report Generation`,description:`Computer can draft a sourced report with an executive summary, evidence notes, tables, and recommended next steps.`},{title:`Connect Your Tools`,description:`Computer can organize sources and findings in Google Sheets, Notion, Gmail, and Slack so research stays easy to share.`},{title:`Remember & Learn`,description:`Computer can remember your preferred source standards, report structure, market definitions, and decision criteria.`},{title:`Monitor & Alert`,description:`Computer can monitor new market signals, competitor changes, and fresh data points, then alert you when the analysis should be updated.`}]});export{t as default};
